package com.example.budgetlife

import kotlin.math.abs

data class CashEvent(val id: String, val date: String, val title: String, val amount: Double, val currency: String, val accountId: String, val kind: String, val sourceType: String, val sourceId: String, val sourceKey: String, val categoryId: String? = null, var status: String = "planned", val tentative: Boolean = false, val note: String? = null, val color: String? = null, val icon: String? = null, val principal: Double? = null, val interest: Double? = null)
data class DayPoint(val date: String, val income: Double, val expense: Double, val interest: Double, val net: Double, val balance: Double, val byAccount: Map<String, Double>)
data class Projection(val days: List<DayPoint>, val events: List<CashEvent>, val interestByAccount: Map<String, Double>, val min: Pair<Double, String>?, val max: Pair<Double, String>?)

class Engine(val state: AppState) {
    private fun acc(id: String) = state.accounts.firstOrNull { it.id == id }
    private fun conv(amount: Double, from: String, to: String) = RatesMath.convert(amount, from, to, state)
    private fun event(e: CashEvent) = e

    fun incomeMonthPayments(src: IncomeSource, ym: String): List<Triple<PayDay, String, Double>> {
        if (ym < src.startYM || (src.endYM != null && ym > src.endYM!!)) return emptyList()
        val ov = src.overrides[ym]; if (ov?.skip == true) return emptyList()
        val gross = ov?.amount ?: src.amount; val net = gross * (1 - (if (src.taxEnabled) src.taxRate else 0.0) / 100.0)
        val fixed = src.payDays.sumOf { it.amount ?: 0.0 }; val definedShare = src.payDays.filter { it.amount == null }.sumOf { it.share ?: 0.0 }
        val free = src.payDays.filter { it.amount == null && it.share == null }
        val amounts = src.payDays.map { pd -> pd.amount ?: run { val share = pd.share ?: if (free.isNotEmpty()) (1 - definedShare).coerceAtLeast(0.0) / free.size else 0.0; net * share } }
        return src.payDays.mapIndexedNotNull { i, pd ->
            val pdo = ov?.payDays?.firstOrNull { it.id == pd.id }; if (pdo?.skipped == true) null else Triple(pd, pdo?.date ?: Dates.resolvePayDay(ym, pd.day, pd.rule), pdo?.amount ?: amounts.getOrElse(i) { 0.0 })
        }
    }

    fun buildEvents(from: String, to: String, topUps: Boolean = true): List<CashEvent> {
        val out = mutableListOf<CashEvent>()
        // Доходы
        for (src in state.incomes) { if (!src.active) continue; val account = acc(src.accountId) ?: continue; var ym = maxOf(Dates.ymOf(from), src.startYM); val endYM = minOf(Dates.ymOf(to), src.endYM ?: Dates.ymOf(to)); var g = 0; while (ym <= endYM && g++ < 600) { for ((pd, date, amountRaw) in incomeMonthPayments(src, ym)) { if (date in from..to) out += event(CashEvent("income:${src.id}:$ym:${pd.id}", date, if (src.payDays.size > 1) "${src.name} · ${pd.label}" else src.name, conv(amountRaw, src.currency, account.currency), account.currency, account.id, "income", "income", src.id, "income:${src.id}:$ym:${pd.id}", src.categoryId, "planned", src.variable && src.overrides[ym]?.amount == null, src.overrides[ym]?.note, "#10d19a", "Wallet")) }; ym = Dates.addYM(ym, 1) } }
        // Подписки
        for (sub in state.subscriptions) { if (!sub.active) continue; val account = acc(sub.accountId) ?: continue; var date = sub.startDate; if (date < from) { val behind = ((Dates.diffDays(date, from).toDouble() / Dates.cycleDays(sub.every, sub.unit)).toInt() - 1).coerceAtLeast(0); date = Dates.addCycles(date, sub.every, sub.unit, behind.toLong()) }; var g = 0; while (date <= to && g++ < 2000) { if (date >= from && (sub.endDate?.let { date <= it } ?: true) && (sub.trialUntil?.let { date > it } ?: true)) { val price = sub.priceHistory.filter { it.first <= date }.maxByOrNull { it.first }?.second ?: sub.amount; out += event(CashEvent("sub:${sub.id}:$date", date, sub.name, -abs(conv(price, sub.currency, account.currency)), account.currency, account.id, "expense", "subscription", sub.id, "sub:${sub.id}:$date", sub.categoryId, "planned", false, sub.note, sub.color, sub.icon)) }; date = Dates.addCycles(date, sub.every, sub.unit, 1) } }
        // Кредиты
        for (cr in state.credits) { if (!cr.active) continue; val account = acc(cr.accountId) ?: continue; if (cr.kind == "credit_card") { for (r in CreditMath.cardSchedule(cr, from, to)) if (r.payment > 0) out += event(CashEvent("credit:${cr.id}:${r.date}", r.date, "${cr.name} · платёж", -abs(conv(r.payment, cr.currency, account.currency)), account.currency, account.id, "expense", "credit", cr.id, "credit:${cr.id}:${r.date}", null, "planned", false, if (cr.repayMode == "full") "Погашение в беспроцентный период" else "В т.ч. проценты ${r.interest.toInt()}", cr.color, "CreditCard", conv(r.principal, cr.currency, account.currency), conv(r.interest, cr.currency, account.currency))) } else { for (r in CreditMath.loanSchedule(cr)) if (r.date in from..to) { val pay = r.payment + cr.extraPayment; out += event(CashEvent("credit:${cr.id}:${r.index}", r.date, "${cr.name} · платёж ${r.index}", -abs(conv(pay, cr.currency, account.currency)), account.currency, account.id, "expense", "credit", cr.id, "credit:${cr.id}:${r.index}", null, "planned", false, "Остаток долга после платежа: ${r.balance.toInt()}", cr.color, "Landmark", conv(r.principal + cr.extraPayment, cr.currency, account.currency), conv(r.interest, cr.currency, account.currency))) } } }
        // Автопополнения
        if (topUps) for (account in state.accounts) { val cfg = account.interest; if (cfg.monthlyTopUp <= 0 || account.archived) continue; var ym = Dates.ymOf(from); var g = 0; while (ym <= Dates.ymOf(to) && g++ < 600) { if ((cfg.topUpStartYM?.let { ym >= it } ?: true) && (cfg.topUpEndYM?.let { ym <= it } ?: true)) { val date = Dates.resolvePayDay(ym, cfg.topUpDay, "exact"); if (date in from..to) out += event(CashEvent("topup:${account.id}:$ym", date, "Пополнение · ${account.name}", abs(cfg.monthlyTopUp), account.currency, account.id, "income", "topup", account.id, "topup:${account.id}:$ym", null, "planned", false, null, "#38c3f5", "PlusCircle")) }; ym = Dates.addYM(ym, 1) } }
        // Операции и факт поверх плана
        val facts = state.transactions.filter { it.status == "done" && it.sourceKey != null }.associateBy { it.sourceKey!! }
        val merged = linkedMapOf<String, CashEvent>()
        fun put(e: CashEvent) { val f = facts[e.sourceKey]; if (f != null) { val fa = acc(f.accountId); merged[e.sourceKey] = e.copy(date = f.date, title = f.title.ifBlank { e.title }, amount = conv(f.amount, f.currency, fa?.currency ?: e.currency), currency = fa?.currency ?: e.currency, accountId = f.accountId, categoryId = f.categoryId ?: e.categoryId, status = "done", tentative = false, note = f.note ?: e.note) } else { val old = merged[e.sourceKey]; if (old == null || (old.status == "planned" && e.status == "done")) merged[e.sourceKey] = e } }
        out.forEach(::put)
        for (tx in state.transactions) { val account = acc(tx.accountId) ?: continue; val dates = if (tx.recurrenceEvery != null) recurrenceDates(tx, from, to) else if (tx.date in from..to) listOf(tx.date) else emptyList(); for (date in dates) { val baseKey = tx.sourceKey ?: "tx:${tx.id}"; val key = if (dates.size > 1) "$baseKey:$date" else baseKey; put(CashEvent(key, date, tx.title, tx.amount, account.currency, account.id, tx.kind, tx.sourceType, tx.sourceId ?: tx.id, key, tx.categoryId, tx.status, false, tx.note, if (tx.amount < 0) "#fb7d8e" else "#10d19a")); if (tx.kind == "transfer" && tx.toAccountId != null) { val target = acc(tx.toAccountId!!); if (target != null) put(CashEvent("$key:in", date, "${tx.title} → ${target.name}", conv(abs(tx.amount), account.currency, target.currency), target.currency, target.id, "transfer", tx.sourceType, tx.sourceId ?: tx.id, "$key:in", null, tx.status, false, tx.note, "#a78bfa")) } } }
        return merged.values.sortedWith(compareBy<CashEvent> { it.date }.thenByDescending { it.amount })
    }

    fun recurrenceDates(tx: Transaction, from: String, to: String): List<String> { val every = tx.recurrenceEvery ?: return listOf(tx.date); var date = tx.date; if (date < from) { val cycles = (Dates.diffDays(date, from).toDouble() / Dates.cycleDays(every, tx.recurrenceUnit ?: "month")).toInt(); date = Dates.addCycles(date, every, tx.recurrenceUnit ?: "month", cycles.toLong()) }; val out = mutableListOf<String>(); var g = 0; while (date <= to && g++ < 2000) { if (date >= from && (tx.recurrenceUntil?.let { date <= it } ?: true)) out += date; date = Dates.addCycles(date, every, tx.recurrenceUnit ?: "month", 1) }; if (out.isEmpty() && tx.date in from..to) out += tx.date; return out }

    fun interestPayoutDates(account: Account, from: String, to: String): List<String> { val cfg = account.interest; if (!cfg.enabled || cfg.annualRate <= 0 || cfg.capitalization == "none") return emptyList(); val out = mutableListOf<String>(); if (cfg.capitalization == "endOfTerm") { cfg.termEnd?.takeIf { it in from..to }?.let { out += it }; return out }; var ym = Dates.ymOf(from); var g = 0; while (ym <= Dates.ymOf(to) && g++ < 800) { val m = java.time.YearMonth.parse(ym); val include = when (cfg.capitalization) { "daily", "monthly" -> true; "quarterly" -> m.monthValue % 3 == 0; "yearly" -> m.monthValue == (cfg.termStart?.let { Dates.parse(it).monthValue } ?: 12); else -> false }; if (include) { val date = m.atDay(minOf(cfg.payoutDay ?: 31, m.lengthOfMonth())).toString(); if (date in from..to && date !in out) out += date }; ym = Dates.addYM(ym, 1) }; return out.sorted() }
    fun estimateMonthlyInterest(account: Account): Double { val cfg = account.interest; if (!cfg.enabled || cfg.annualRate <= 0) return 0.0; return (account.balance + cfg.monthlyTopUp / 2) * cfg.annualRate / 100.0 / 12.0 }

    fun project(from: String, to: String, withInterest: Boolean = true, startFrom: String? = null): Projection {
        val today = Dates.today(); val loopStart = startFrom ?: if (from < today) today else from
        val events = buildEvents(from, to); val byDate = events.groupBy { it.date }
        val balances = state.accounts.associate { it.id to it.balance }.toMutableMap(); val accrued = mutableMapOf<String, Double>(); val payoutDates = state.accounts.associate { it.id to interestPayoutDates(it, loopStart, to).toSet() }
        val interestByAccount = mutableMapOf<String, Double>(); val interestEvents = mutableListOf<CashEvent>(); val days = mutableListOf<DayPoint>(); var min: Pair<Double, String>? = null; var max: Pair<Double, String>? = null
        if (Dates.parse(to).isBefore(Dates.parse(loopStart))) return Projection(days, events, interestByAccount, null, null)
        var cursor = Dates.parse(loopStart); val totalDays = (Dates.diffDays(loopStart, to) + 1).toInt()
        for (i in 0 until totalDays) { val date = cursor.toString(); var income = 0.0; var expense = 0.0; var interestToday = 0.0
            for (e in byDate[date].orEmpty().filterNot { it.status == "done" && it.date <= today }) { balances[e.accountId] = (balances[e.accountId] ?: 0.0) + e.amount; val base = conv(e.amount, e.currency, state.settings.baseCurrency); if (base >= 0) income += base else expense += -base }
            if (withInterest) for (account in state.accounts) { val cfg = account.interest; if (!cfg.enabled || cfg.annualRate <= 0 || cfg.capitalization == "none" || account.archived) continue; val bal = balances[account.id] ?: 0.0; val daily = bal * cfg.annualRate / 100.0 / if (cursor.isLeapYear) 366.0 else 365.0; accrued[account.id] = (accrued[account.id] ?: 0.0) + daily; if (cfg.capitalization == "daily") balances[account.id] = bal + daily
                if (payoutDates[account.id]?.contains(date) == true) { val sum = accrued[account.id] ?: 0.0; interestByAccount[account.id] = (interestByAccount[account.id] ?: 0.0) + conv(sum, account.currency, state.settings.baseCurrency); interestToday += conv(sum, account.currency, state.settings.baseCurrency); if (cfg.capitalization != "daily") { if (cfg.payoutMode == "payout" && cfg.payoutAccountId != null && cfg.payoutAccountId != account.id) { val target = acc(cfg.payoutAccountId!!); if (target != null) { val amount = conv(sum, account.currency, target.currency); balances[target.id] = (balances[target.id] ?: 0.0) + amount; interestEvents += CashEvent("interest:${account.id}:$date", date, "Проценты · ${account.name}", amount, target.currency, target.id, "interest", "interest", account.id, "interest:${account.id}:$date", null, "planned", false, "Выплата процентов на другой счёт", "#34e5b0", "Percent") } } else { balances[account.id] = (balances[account.id] ?: 0.0) + sum; interestEvents += CashEvent("interest:${account.id}:$date", date, "Проценты · ${account.name}", sum, account.currency, account.id, "interest", "interest", account.id, "interest:${account.id}:$date", null, "planned", false, "Капитализация процентов", "#34e5b0", "Percent") } } else { interestEvents += CashEvent("interest:${account.id}:$date", date, "Проценты · ${account.name}", sum, account.currency, account.id, "interest", "interest", account.id, "interest:${account.id}:$date", null, "planned", false, "Ежедневная капитализация", "#34e5b0", "Percent") }; accrued[account.id] = 0.0 } }
            var total = 0.0; val byAccount = linkedMapOf<String, Double>(); for (account in state.accounts) { byAccount[account.id] = balances[account.id] ?: 0.0; if (account.includeInTotal && !account.archived) total += conv(balances[account.id] ?: 0.0, account.currency, state.settings.baseCurrency) }
            days += DayPoint(date, income, expense, interestToday, income - expense, total, byAccount); if (min == null || total < min!!.first) min = total to date; if (max == null || total > max!!.first) max = total to date; cursor = cursor.plusDays(1) }
        return Projection(days, (events + interestEvents).sortedWith(compareBy<CashEvent> { it.date }.thenByDescending { it.amount }), interestByAccount, min, max)
    }

    fun totals(events: List<CashEvent>): Triple<Double, Double, Double> { var inc = 0.0; var exp = 0.0; for (e in events) { val v = conv(e.amount, e.currency, state.settings.baseCurrency); if (v >= 0) inc += v else exp += -v }; return Triple(inc, exp, inc - exp) }
    fun categoryBreakdown(events: List<CashEvent>, incomeKind: Boolean): List<Triple<Category?, Double, String>> { val map = linkedMapOf<String, Double>(); for (e in events) { val v = conv(e.amount, e.currency, state.settings.baseCurrency); if ((v >= 0) != incomeKind) continue; val key = e.categoryId ?: "__none__"; map[key] = (map[key] ?: 0.0) + abs(v) }; return map.entries.map { (key, value) -> Triple(state.categories.firstOrNull { it.id == key }, value, key) }.sortedByDescending { it.second } }
}
